"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

Step 0 item 7 (P1 v0.3, sections 4 and 6.4): the "new recordings" subset from Freesound (report-only).

Uploads created on or after 2023-06-01 (after FSD50K and WavCaps were built), CC0 or CC BY, 0.5-30 s, for five event
types: doorbell, knock, phone ring, phone vibration, intercom/door buzzer. Curated from title/tags/description with
the rules of step0_curate_pools.py plus a contamination rule (no other named sound source), downloaded in original
quality (OAuth), then fingerprint-checked against the FSD50K pools, MUSAN noise and the Commons clips: any match is
excluded (an old sound re-uploaded is not new). Uploader groups go to test or replication 2:1 (seeded).

usage: python -I scripts/step0_freesound_subset.py search|download|check  (outputs under data/freesound_new and
       results/step0/freesound_new_subset.json)
"""
import glob
import json
import os
import random
import re
import sys
import time
import urllib.error

sys.path.insert(0, os.path.dirname(__file__))
import freesound_client as FS  # noqa: E402
import step0_curate_pools as CP  # noqa: E402

OUT_DIR = "data/freesound_new"
CAND = "results/step0/freesound_new_candidates.json"
RESULT = "results/step0/freesound_new_subset.json"
QUERIES = {
    "doorbell": ["doorbell", "door bell", "ding dong door"],
    "knock": ["knock door", "door knock", "knocking door"],
    "phone": ["phone ringing", "telephone ring", "ringtone", "phone ring"],
    "vibration": ["phone vibrate", "phone vibration", "vibrating phone"],
    "intercom": ["intercom", "door buzzer", "entry buzzer"],
}
FILTER = 'created:[2023-06-01T00:00:00Z TO *] duration:[0.5 TO 30]'
OK_LICENSE = re.compile(r"creativecommons\.org/(publicdomain/zero/1\.0|licenses/by/[34]\.0)/?$")
CONTAM = re.compile(r"\bdogs?\b|bark|speech|talk|voice|conversation|music|song|ambien|street|traffic|crowd|rain|"
                    r"wind\b|birds?\b|\btv\b|television|radio|laugh|scream|footstep", re.I)
MAX_FSD50K_ID = 452000          # every FSD50K clip id is below this; new uploads are far above


def assign(kind, text, title_tags):
    if CONTAM.search(text) and kind not in ("vibration",):
        return None
    if kind == "doorbell":
        if CP.INTERCOM.search(text):
            return "intercom"
        return None if CP.DOORBELL_NEG.search(title_tags) else "doorbell"
    if kind == "knock":
        return "knock" if CP.KNOCK_POS.search(title_tags) and not CP.KNOCK_NEG.search(title_tags) else None
    if kind == "phone":
        if CP.VIBRATION.search(text):
            return "vibration"
        if CP.RINGTONE_NEG.search(title_tags):
            return None
        return "phone" if CP.RING_POS.search(text) and not CP.RING_NEG.search(text) else None
    if kind == "vibration":
        return "vibration" if CP.VIBRATION.search(text) and not re.search(r"\bmusic|song", text, re.I) else None
    if kind == "intercom":
        return "intercom" if re.search(r"intercom|door.?buzz|entry.?buzz|entry.?phone|door.?phone", text, re.I) \
            and not re.search(r"game|quiz|alarm clock|bee\b|insect", text, re.I) else None
    return None


def search():
    seen, cands = set(), {}
    for kind, queries in QUERIES.items():
        for q in queries:
            page = 1
            while True:
                st, js = FS.get("/search/", params={"query": q, "filter": FILTER, "page": page, "page_size": 150,
                                                    "fields": "id,name,tags,description,license,username,created,"
                                                              "duration,type,samplerate,channels"})
                for s in js.get("results", []):
                    if s["id"] in seen or not OK_LICENSE.search(s["license"]) or s["id"] < MAX_FSD50K_ID:
                        continue
                    seen.add(s["id"])
                    text = " ".join([s["name"], " ".join(s["tags"]), s.get("description", "")])
                    pool = assign(kind, text, s["name"] + " " + " ".join(s["tags"]))
                    if pool:
                        cands[str(s["id"])] = {"pool": pool, "query_kind": kind, "query": q, "title": s["name"],
                                               "uploader": s["username"], "license": s["license"],
                                               "created": s["created"], "duration": s["duration"],
                                               "type": s["type"]}
                if not js.get("next") or page >= 10:
                    break
                page += 1
                time.sleep(1.1)
            time.sleep(1.1)
    json.dump(cands, open(CAND, "w", encoding="utf-8"), indent=1, ensure_ascii=False)
    from collections import Counter
    print("candidates:", dict(Counter(v["pool"] for v in cands.values())),
          "uploaders:", {p: len({v["uploader"] for v in cands.values() if v["pool"] == p})
                         for p in sorted({v["pool"] for v in cands.values()})})


def download():
    cands = json.load(open(CAND, encoding="utf-8"))
    raw = os.path.join(OUT_DIR, "raw")
    os.makedirs(raw, exist_ok=True)
    done = {os.path.splitext(f)[0] for f in os.listdir(raw)}
    n = 0
    for sid, v in cands.items():
        if sid in done or v["type"] in ("m4a",):
            continue
        for attempt in range(3):
            try:
                st, data = FS.get(f"/sounds/{sid}/download/", oauth=True, raw=True)
                open(os.path.join(raw, f"{sid}.{v['type']}"), "wb").write(data)
                n += 1
                break
            except urllib.error.HTTPError as e:
                if e.code == 429:
                    time.sleep(60)
                elif attempt == 2:
                    print("failed", sid, e.code)
        time.sleep(1.1)
    print("downloaded", n, "files; total in raw:", len(os.listdir(raw)))


def check():
    import numpy as np  # noqa: F401
    import step0_fingerprint as F
    cands = json.load(open(CAND, encoding="utf-8"))
    thr = json.load(open("results/step0/fingerprint_groups.json", encoding="utf-8"))["threshold_aligned_matches"]
    ref = sorted(glob.glob("data/fsd50k_sel/*.wav")) + sorted(glob.glob("data/musan_dl/musan/noise/*/*.wav")) \
        + sorted(glob.glob("data/commons4_testonly/*"))
    index = F.Index([F.fingerprint(F.load(p)) for p in ref])
    files = {os.path.splitext(os.path.basename(p))[0]: p for p in glob.glob(os.path.join(OUT_DIR, "raw", "*"))}
    keep, dropped = {}, {}
    for sid, p in sorted(files.items()):
        try:
            y = F.load(p)
        except Exception as e:  # noqa: BLE001
            dropped[sid] = f"unreadable ({type(e).__name__})"
            continue
        best = index.best(*F.fingerprint(y))
        hit = max(best.items(), key=lambda kv: kv[1], default=(None, 0))
        if hit[1] >= thr:
            dropped[sid] = f"matches {os.path.basename(ref[hit[0]])} ({hit[1]})"
        else:
            keep[sid] = cands[sid]
    ups = sorted({v["uploader"] for v in keep.values()})
    random.Random(2).shuffle(ups)
    split_of = {u: ("test" if i % 3 < 2 else "replication") for i, u in enumerate(ups)}
    for v in keep.values():
        v["split"] = split_of[v["uploader"]]
    json.dump({"threshold": thr, "kept": keep, "dropped": dropped}, open(RESULT, "w", encoding="utf-8"), indent=1,
              ensure_ascii=False)
    from collections import Counter
    print("kept by pool/split:", dict(Counter((v["pool"], v["split"]) for v in keep.values())))
    print("dropped:", len(dropped), dict(Counter(d.split(" ")[0] for d in dropped.values())))


if __name__ == "__main__":
    {"search": search, "download": download, "check": check}[sys.argv[1]]()
